import { Routes, Route } from "react-router-dom";
import Sidebar from "./components/siderbar";
import TopBar from "./components/topBar";
import Dashboard from "./components/dashboard";

function ComingSoon({ title }) {
  return (
    <div className="min-h-full flex flex-col items-center justify-center text-center px-8 py-20">
      <p className="font-mono text-xs tracking-widest uppercase text-brand">
        {title}
      </p>
      <h1 className="mt-3 text-5xl font-bold tracking-tight">Coming soon</h1>
      <p className="mt-4 text-lg text-slate-500">
        We're still building this page.
      </p>
    </div>
  );
}

function App() {
  return (
    <div className="flex h-screen w-screen overflow-hidden">
      <Sidebar />
      <div className="flex-1 flex flex-col min-w-0">
        <TopBar />
        <main className="flex-1 overflow-auto">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/groups" element={<ComingSoon title="Groups" />} />
            <Route path="/friends" element={<ComingSoon title="Friends" />} />
            <Route path="/expenses" element={<ComingSoon title="Expenses" />} />
            <Route path="/settlements" element={<ComingSoon title="Settlements" />} />
            <Route path="/join-group" element={<ComingSoon title="Join a group" />} />
            <Route path="/settings" element={<ComingSoon title="Settings" />} />
            <Route path="/profile" element={<ComingSoon title="Profile" />} />
            <Route path="*" element={<ComingSoon title="Not found" />} />
          </Routes>
        </main>
      </div>
    </div>
  );
}

export default App;
